#mysteries{位置：相对；溢出：隐藏}
    #mysteries .wrap{位置：相对；z-index：3}
    .myst-filterbar{显示：flex；flex-wrap：wrap；间隙：20px 28px；align-items：flex-end；margin-bottom：14px}
    .myst-filter-group{显示：flex;flex-direction:column;gap:9px;min-width:0}
    .myst-filter-label{font-family:"空格单色",ui-monospace,monospace;font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:#d3a8c2}
    .myst-chip-row{显示：flex;flex-wrap:wrap;间隙：8px}
    .myst-芯片{
      显示：inline-flex；对齐项目：中心；间隙：8px；光标：指针；
      内边距：9px 15px；边框半径：999px；
      font-family:"空格单色",ui-monospace,monospace;font-size:11px;
      字母间距：.14em；文本转换：大写；颜色：#f4e3d7；
      背景:rgba(20,7,44,.72);边框:1px实心rgba(255,45,124,.3);
      过渡：变换 .15s 缓动，box-shadow .2s 缓动，边框颜色 .2s 缓动；
    }
    .myst-chip:hover{变换:translateY(-1px);边框颜色:rgba(255,45,124,.65);box-shadow:0 0 20px rgba(255,45,124,.25)}
    .myst-chip.active{
      背景：var(--vi-grad-sunset,线性渐变(90deg,#ff2d7c,#ff8a3d 52%,#ffd166));
      颜色:var(--vi-ink,#33051c);边框颜色:透明;字体粗细:700;
      盒子阴影：0 8px 22px -8px rgba(255,45,124,.65);
    }
    .myst-chip .myst-dot{宽度:8px;高度:8px;边框半径:99px;flex:0 0 自动}
    .myst-chip.active .myst-dot{轮廓:1px实心rgba(51,5,28,.4)}
    .myst-dot--resolved{背景:线性渐变(135deg,var(--vi-gold,#ffd166),#7ee08c)}
    .myst-dot--open{背景:var(--vi-pink,#ff2d7c);box-shadow:0 0 10px rgba(255,45,124,.8)}
    .myst-dot--lenda{背景:var(--vi-purple,#7b2ff7);box-shadow:0 0 10px rgba(123,47,247,.8)}
    .myst-dot--all{背景:#f4e3d7}
    .myst-chip 小{
      字体大小：10px；填充：2px 7px；边框半径：99px；字母间距：.08em；
      背景:rgba(11,13,42,.55);颜色:继承;边框:1px实心rgba(255,255,255,.18);
    }
    .myst-chip.active 小{背景:rgba(51,5,28,.22);边框颜色:rgba(51,5,28,.3)}
    .myst-选择{
      外观：无；-webkit-外观：无；光标：指针；最小宽度：220px；
      内边距：10px 38px 10px 14px；边框半径：10px；
      font-family:"空格单色",ui-monospace,monospace;font-size:12px;letter-spacing:.06em;
      颜色:#fff5ec;背景:rgba(20,7,44,.72);边框:1px实心rgba(255,45,124,.3);
      背景图像：url（“数据：图像/ svg + xml;utf8，<svg xmlns ='http://www.w3.org/2000/svg'宽度='12'高度='8'viewBox ='0 0 12 8'><路径d ='M1 1l5 5 5-5'填充='无'笔画='%23ff2d7c'笔划宽度='2'笔划-linecap='round'/></svg>");
      背景重复：无重复；背景位置：右14px中心；
    }
    .myst-select:焦点{轮廓:无;边框颜色:rgba(255,45,124,.7);box-shadow:0 0 18px rgba(255,45,124,.3)}
    .myst-选择选项{背景:#0b0d2a;颜色:#fff5ec}
    .myst-状态-desc{
      边距：0 0 18px；最大宽度：760px；颜色：#d9c3d2；字体大小：14px；行高：1.6；
      左边框：3px 实心 rgba(255,45,124,.55);左填充：14px;
    }
    .myst-grid{显示：网格；网格模板列：重复（自动填充，minmax（330px，1fr））；间隙：18px；对齐项目：开始}
    .myst-card{显示：flex；flex-方向：列；间隙：0；填充：22px 22px 18px}
    .myst-card-top{显示：flex;align-items:center;justify-content:space- Between;gap:10px;flex-wrap:wrap;margin-bottom:14px}
    .myst-file-no{font-family:"空格 Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.22em;color:#b98ca9;text-transform:uppercase}
    .myst-stamp{变换：旋转（-2deg）;字体大小：10px;字母间距：.2em;填充：6px 13px}
    .myst-stamp--已解决{
      背景：线性渐变（90deg，var（--vi-gold，#ffd166），#7ee08c）；
      颜色:var(--vi-ink,#33051c);盒子阴影:0 8px 22px -8px rgba(255,209,102,.7),0 0 20px rgba(126,224,140,​​.25);
    }
    .myst-stamp--open{颜色:var(--vi-pink,#ff2d7c);box-shadow:0 0 22px rgba(255,45,124,.4)}
    .myst-stamp--图例{
      颜色:#cfa9ff;盒子阴影:0 0 22px rgba(123,47,247,.45);
      背景：
        线性渐变(rgba(26,9,54,.9),rgba(26,9,54,.9)) 填充框，
        线性渐变（90deg，var（--vi-purple，#7b2ff7），var（--vi-pink-2，#f152ff））边框；
    }
    .myst-游戏芯片{
      显示：inline-flex；对齐项目：中心；间隙：6px；边距底部：10px；
      font-family:"空格单色",ui-monospace,monospace;font-size:10px;
      字母间距：.18em；文本转换：大写；颜色：var(--vi-gold,#ffd166);
    }
    .myst-game-chip::before{内容：""；宽度：14px；高度：1px；背景：var(--vi-gold，#ffd166)；不透明度：.7}
    .myst-card h3{边距:0 0 10px;字体大小:20px;行高:1.25;颜色:#fff5ec}
    .myst-desc{边距:0;颜色:#d9c8d4;字体大小:14px;行高:1.62}
    .myst-toggle{margin-top:16px;align-self:flex-start}
    .myst-body{margin-top:16px;padding-top:16px;border-top:1px 虚线 rgba(255,45,124,.35)}
    .myst-证据-标签{
      显示：flex；对齐项目：中心；间隙：8px；边距：16px 0 4px；
      font-family:"空格单色",ui-monospace,monospace;font-size:10px;
      字母间距：.26em；文本转换：大写；颜色：#ff9ec4；
    }
    .myst-evidence-label:first-child{margin-top:0}
    .myst-evidence-label::after{内容:"";flex:1;高度:1px;背景:rgba(255,45,124,.25)}
    .myst-list{列表样式：无；边距：8px 0 0；填充：0}
    .myst-list li{显示：flex；间隙：10px；对齐项目：基线；边距底部：8px；颜色：#e6d6dd；字体大小：13.5px；行高：1.6}
    .myst-idx{
      flex:0 0 auto;font-family:"空格单色",ui-monospace,monospace;font-size:10px;
      字母间距:.08em;颜色:var(--vi-gold,#ffd166);不透明度:.85;最小宽度:30px;
    }
    .myst-决议{
      顶部边距：18px；内边距：14px 16px；边框半径：10px；
      边框:1px 虚线 rgba(255,209,102,.6);背景:rgba(255,209,102,.07);
    }
    .myst-resolution .myst-evidence-label{颜色:var(--vi-gold,#ffd166);margin-top:0}
    .myst-resolution .myst-evidence-label::after{背景:rgba(255,209,102,.35)}
    .myst-分辨率 p{边距:8px 0 0;颜色:#ffe9bd;字体大小:13.5px;行高:1.62}
    .myst-哪里{
      显示：flex；间隙：10px；对齐项目：基线；边距顶部：16px；
      font-family:"空格单色",ui-monospace,monospace;font-size:12px;
      颜色：#cdb4c6；行高：1.55；
    }
    .myst-where svg{flex:0 0 auto;宽度:14px;高度:14px;变换:translateY(2px);颜色:var(--vi-pink,#ff2d7c)}
    .myst-空{
      填充：34px 26px；文本对齐：居中；颜色：#d3a8c2；
      font-family:"Space Mono",ui-monospace,monospace;font-size:13px;letter-spacing:.08em;
    }
    @media（最大宽度：760px）{
      .myst-filterbar{flex-direction:column;align-items:stretch}
      .myst-选择{宽度：100%}
      .myst-grid{网格模板列:1fr}
      .myst-card{填充：18px 16px 16px}
    }
    @media（首选减少运动：减少）{
      .myst-chip,.myst-chip:hover{变换:无;过渡:无}
    }
